// Package client is a typed GraphQL client for the Unraid API, generated by genqlient.
package client

//go:generate go tool genqlient genqlient.yaml

import (
	"crypto/tls"
	"errors"
	"net/http"
	"time"

	"github.com/Khan/genqlient/graphql"
)

type apiKeyTransport struct {
	apiKey string
	base   http.RoundTripper
}

func (t *apiKeyTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	req = req.Clone(req.Context())
	req.Header.Set("x-api-key", t.apiKey)
	return t.base.RoundTrip(req)
}

// New returns a GraphQL client authenticated with an Unraid API key.
func New(endpoint, apiKey string, insecureSkipVerify bool) (graphql.Client, error) {
	if endpoint == "" || apiKey == "" {
		return nil, errors.New("endpoint and api_key are required")
	}
	base := http.DefaultTransport.(*http.Transport).Clone()
	if insecureSkipVerify {
		base.TLSClientConfig = &tls.Config{InsecureSkipVerify: true} //nolint:gosec // explicit opt-in for self-signed Unraid certs
	}
	httpClient := &http.Client{
		Timeout:   60 * time.Second,
		Transport: &apiKeyTransport{apiKey: apiKey, base: base},
	}
	return graphql.NewClient(endpoint, httpClient), nil
}
